@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  /* Ankara Univ Colors */
  --color-primary: #1a237e;     /* Deep Navy Blue */
  --color-primary-light: #534bae;
  --color-primary-dark: #000051;
  --color-accent: #c62828;      /* Deep Red */
  --color-accent-light: #ff5f52;
  --color-accent-dark: #8e0000;

  /* Dark mode background colors */
  --bg-main: #0f111a;
  --bg-card: rgba(26, 30, 41, 0.7); /* Glassmorphism start */
  --bg-card-hover: rgba(36, 42, 56, 0.85);

  /* Text */
  --text-primary: #f5f5f5;
  --text-secondary: #b0bec5;
  --text-muted: #78909c;

  /* Glass effects */
  --glass-border: rgba(255, 255, 255, 0.08);
  --glass-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);
  --blur-amount: blur(12px);

  /* Rounded corners */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 0.2s ease;
  --transition-medium: 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-main);
  background-image: 
    radial-gradient(circle at 15% 50%, rgba(26, 35, 126, 0.15) 0%, transparent 50%),
    radial-gradient(circle at 85% 30%, rgba(198, 40, 40, 0.1) 0%, transparent 40%);
  background-attachment: fixed;
  color: var(--text-primary);
  min-height: 100vh;
  overflow-x: hidden;
  line-height: 1.5;
}

/* Glassmorphism Classes */
.glass-panel {
  background: var(--bg-card);
  backdrop-filter: var(--blur-amount);
  -webkit-backdrop-filter: var(--blur-amount);
  border: 1px solid var(--glass-border);
  box-shadow: var(--glass-shadow);
  border-radius: var(--radius-lg);
  padding: 2rem;
}

.glass-input {
  background: rgba(15, 17, 26, 0.6);
  border: 1px solid var(--glass-border);
  color: var(--text-primary);
  padding: 0.75rem 1rem;
  border-radius: var(--radius-sm);
  outline: none;
  width: 100%;
  transition: var(--transition-fast);
  font-family: inherit;
}

.glass-input:focus {
  border-color: var(--color-primary-light);
  box-shadow: 0 0 0 2px rgba(83, 75, 174, 0.25);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: var(--transition-fast);
  font-family: inherit;
}

.btn-primary {
  background: linear-gradient(135deg, var(--color-primary), var(--color-primary-light));
  color: white;
  box-shadow: 0 4px 12px rgba(26, 35, 126, 0.4);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(26, 35, 126, 0.6);
  filter: brightness(1.1);
}

.btn-accent {
  background: linear-gradient(135deg, var(--color-accent), var(--color-accent-light));
  color: white;
  box-shadow: 0 4px 12px rgba(198, 40, 40, 0.4);
}

.btn-accent:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(198, 40, 40, 0.6);
  filter: brightness(1.1);
}

.btn-outline {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--glass-border);
}

.btn-outline:hover {
  background: rgba(255, 255, 255, 0.05);
  border-color: var(--text-secondary);
}

.badge {
  padding: 0.25rem 0.75rem;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.badge-success {
  background: rgba(46, 125, 50, 0.2);
  color: #81c784;
  border: 1px solid rgba(46, 125, 50, 0.3);
}

.badge-warning {
  background: rgba(245, 124, 0, 0.2);
  color: #ffb74d;
  border: 1px solid rgba(245, 124, 0, 0.3);
}

.badge-info {
  background: rgba(2, 119, 189, 0.2);
  color: #4fc3f7;
  border: 1px solid rgba(2, 119, 189, 0.3);
}

/* Layout Utilities */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
}

.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--glass-border);
}

.grid-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 1.5rem;
}

/* Typography Utilities */
h1, h2, h3, h4 { color: white; }
.text-muted { color: var(--text-muted); }
.text-accent { color: var(--color-accent-light); }
.text-center { text-align: center; }
.mt-1 { margin-top: 0.5rem; }
.mt-2 { margin-top: 1rem; }
.mt-3 { margin-top: 1.5rem; }
.mt-4 { margin-top: 2rem; }
.mb-1 { margin-bottom: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.mb-4 { margin-bottom: 2rem; }

/* Table styles */
.glass-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  margin-top: 1rem;
}
.glass-table th, .glass-table td {
  padding: 1rem;
  text-align: left;
  border-bottom: 1px solid var(--glass-border);
}
.glass-table th {
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  font-size: 0.85rem;
  letter-spacing: 0.05em;
}
.glass-table tr:last-child td { border-bottom: none; }
.glass-table tbody tr { transition: var(--transition-fast); }
.glass-table tbody tr:hover { background: rgba(255, 255, 255, 0.03); }

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-fade-in {
  animation: fadeIn 0.4s ease forwards;
}

